__mod["core.interface"] = function(...)
-- Builds the table for fb.provide("pokemon.core", tbl).
local M = {}

local METHODS = { "team", "box", "box_count", "location", "battle", "encounters", "badges" }
local FEATURE = {
  team = "team", box = "box", location = "location",
  battle = "battle", encounters = "encounters", badges = "badges",
}

local function has(adapter, name)
  return adapter ~= nil and type(adapter[name]) == "function"
end

-- entry: games.lua entry, detected: info from games.detect, adapter: adapter object or nil
function M.new(entry, detected, adapter)
  local api = {}

  function api.info()
    local features = {}
    for method, key in pairs(FEATURE) do features[key] = has(adapter, method) end
    local language = detected and detected.language or nil
    if has(adapter, "language") then language = adapter:language() or language end
    local revision
    if has(adapter, "revision") then revision = adapter:revision() end
    return {
      game_id = entry.id,
      name = entry.name,
      gen = entry.gen,
      system = entry.system,
      version = entry.version,
      language = language,
      revision = revision,
      supported = adapter ~= nil,
      features = features,
    }
  end

  for _, method in ipairs(METHODS) do
    api[method] = function(...)
      if not has(adapter, method) then return nil, "unsupported" end
      return adapter[method](adapter, ...)
    end
  end

  return api
end

return M

end
__mod["core.serialize"] = function(...)
-- Deterministic serialization (sorted keys), used to compare values for changes.
local M = {}

local function ser(v, out)
  local t = type(v)
  if t == "table" then
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b)
      local ta, tb = type(a), type(b)
      if ta ~= tb then return ta < tb end
      return a < b
    end)
    out[#out + 1] = "{"
    for _, k in ipairs(keys) do
      out[#out + 1] = type(k) == "string" and string.format("%q", k) or tostring(k)
      out[#out + 1] = "="
      ser(v[k], out)
      out[#out + 1] = ","
    end
    out[#out + 1] = "}"
  elseif t == "string" then
    out[#out + 1] = string.format("%q", v)
  else
    out[#out + 1] = tostring(v)
  end
end

function M.serialize(v)
  local out = {}
  ser(v, out)
  return table.concat(out)
end

return M

end
__mod["gen6.growth"] = function(...)
-- EXP <-> level for the six standard growth curves (formulas only, no tables).
-- Rate IDs follow the games' personal data (PKHeX: Experience.GetEXPTable /
-- PersonalInfo.EXPGrowth): 0 medium fast, 1 erratic, 2 fluctuating,
-- 3 medium slow, 4 fast, 5 slow.
-- Formulas: Bulbapedia "Experience" (integer division rounds down).
local M = {}

M.MEDIUM_FAST, M.ERRATIC, M.FLUCTUATING = 0, 1, 2
M.MEDIUM_SLOW, M.FAST, M.SLOW = 3, 4, 5
M.MAX_LEVEL = 100

-- Total EXP needed to reach level n (1..100) with the given rate; nil for bad input.
function M.exp_for_level(rate, n)
  if math.type(n) ~= "integer" or n < 1 or n > 100 then return nil end
  if n == 1 then return 0 end
  local c = n * n * n
  if rate == 0 then
    return c
  elseif rate == 1 then
    if n < 50 then return c * (100 - n) // 50 end
    if n < 68 then return c * (150 - n) // 100 end
    if n < 98 then return c * ((1911 - 10 * n) // 3) // 500 end
    return c * (160 - n) // 100
  elseif rate == 2 then
    if n < 15 then return c * ((n + 1) // 3 + 24) // 50 end
    if n < 36 then return c * (n + 14) // 50 end
    return c * (n // 2 + 32) // 50
  elseif rate == 3 then
    return 6 * c // 5 - 15 * n * n + 100 * n - 140
  elseif rate == 4 then
    return 4 * c // 5
  elseif rate == 5 then
    return 5 * c // 4
  end
  return nil
end

-- Level (1..100) for an EXP value; nil when rate or exp are invalid.
function M.level_from_exp(rate, exp)
  if math.type(exp) ~= "integer" or exp < 0 then return nil end
  if M.exp_for_level(rate, 2) == nil then return nil end
  local level = 1
  for n = 2, 100 do
    if exp >= M.exp_for_level(rate, n) then level = n else break end
  end
  return level
end

return M

end
__mod["gen6.oras"] = function(...)
-- Adapter for Pokemon Omega Ruby / Alpha Sapphire (3DS, Gen 6).
-- Addresses: docs/games/omega-ruby-alpha-sapphire.md. Only team, boxes and
-- revision are backed; location/battle/encounters/badges are not implemented.
local pk6 = require("gen6.pk6")
local growth = require("gen6.growth")
local personal = require("gen6.personal")

local M = {}

M.PARTY_SLOTS = 6
M.PARTY_STRIDE = 0x1E4 -- Rev 2 EUR: member 2 sits at +0x3C8 = 2 x stride; order/stride still open
M.PARTY_SIZE = pk6.SIZE_PARTY
M.BOX_COUNT = 31
M.BOX_SLOTS = 30
M.BOX_SIZE = pk6.SIZE_STORED
M.ORIGIN_AS, M.ORIGIN_OR = 26, 27 -- PKHeX GameVersion (X 24, Y 25)

-- Candidate address sets, checked in this order.
M.REVISIONS = {
  { name = "rev2", party = 0x08CF727C, box = 0x08C9A144 },   -- verified: Omega Ruby EUR Rev 2
  { name = "rev0_1", party = 0x08CFB26C, box = 0x08C9E134 }, -- community addresses, unverified
}

local PARTY_LEN = (M.PARTY_SLOTS - 1) * M.PARTY_STRIDE + M.PARTY_SIZE
local BOX_LEN = M.BOX_COUNT * M.BOX_SLOTS * M.BOX_SIZE

local function read_record(fb, addr, size)
  local raw = fb.memory.bytes(addr, size)
  if not raw or #raw < size then return nil end
  if not (fb.codec and fb.codec.pk6_decrypt) then return nil end
  local plain, ok = fb.codec.pk6_decrypt(raw)
  if not plain or not ok then return nil end
  local rec = pk6.parse(plain)
  if not rec or rec.species < 1 or rec.species > pk6.MAX_SPECIES then return nil end
  return rec
end

function M.attach(ctx)
  local fb = ctx.fb
  local pers = personal.new(fb)
  local chosen

  for _, set in ipairs(M.REVISIONS) do
    fb.memory.watch("oras." .. set.name .. ".party", set.party, PARTY_LEN)
    fb.memory.watch("oras." .. set.name .. ".box", set.box, BOX_LEN)
  end

  local function detect()
    if chosen then return chosen end
    for _, set in ipairs(M.REVISIONS) do
      if read_record(fb, set.party, M.PARTY_SIZE) then chosen = set; return chosen end
    end
    return nil
  end

  local function finish(rec)
    local rate = pers.growth_rate(rec.species)
    if rate then rec.level = growth.level_from_exp(rate, rec.exp) end
    return rec
  end

  local obj = {}

  function obj:revision()
    local set = detect()
    if not set then return nil, "not_ready" end
    return set.name
  end

  -- Heuristic (no save-block language offset is sourced): the language of the
  -- player's own catches. Party records with origin game AS/OR (PKHeX
  -- GameVersion 26/27) are grouped by OT ID/SID; the largest group (earliest
  -- slot on ties) is taken as the player's and its first member's language
  -- is returned. A Pokemon traded in from another-language OR/AS game can
  -- fool it. nil when there is no such record.
  function obj:language()
    local team = self:team()
    if not team then return nil end
    local groups, order = {}, {}
    for _, r in ipairs(team) do
      if (r.origin_game == M.ORIGIN_AS or r.origin_game == M.ORIGIN_OR) and r.language then
        local key = r.ot_id .. ":" .. r.ot_sid
        if not groups[key] then groups[key] = { n = 0, first = r }; order[#order + 1] = key end
        groups[key].n = groups[key].n + 1
      end
    end
    local best
    for _, key in ipairs(order) do
      if not best or groups[key].n > best.n then best = groups[key] end
    end
    return best and best.first.language or nil
  end

  function obj:team()
    local set = detect()
    if not set then return nil, "not_ready" end
    local out = {}
    for i = 1, M.PARTY_SLOTS do
      local rec = read_record(fb, set.party + (i - 1) * M.PARTY_STRIDE, M.PARTY_SIZE)
      if rec then rec.slot = i; out[#out + 1] = finish(rec) end
    end
    return out
  end

  function obj:box_count()
    if not detect() then return nil, "not_ready" end
    return M.BOX_COUNT
  end

  function obj:box(n)
    local set = detect()
    if not set then return nil, "not_ready" end
    if math.type(n) ~= "integer" or n < 1 or n > M.BOX_COUNT then return nil, "out_of_range" end
    local base = set.box + (n - 1) * M.BOX_SLOTS * M.BOX_SIZE
    if not fb.memory.bytes(base, M.BOX_SLOTS * M.BOX_SIZE) then return nil, "not_ready" end
    local out = {}
    for s = 1, M.BOX_SLOTS do
      local rec = read_record(fb, base + (s - 1) * M.BOX_SIZE, M.BOX_SIZE)
      if rec then rec.slot = s; rec.box = n; out[#out + 1] = finish(rec) end
    end
    return out
  end

  return obj
end

return M

end
__mod["gen6.personal"] = function(...)
-- Growth rate per species, read at runtime from the user's own game files
-- (RomFS personal GARC). Nothing from the game is shipped or persisted; the
-- values live in a Lua table cache only.
--
-- ORAS personal data (community-documented, all to verify locally):
--   path  : candidates "/a/1/9/5" and "/a/1/9/6", tried in order; the first one
--           whose data validates as a personal table is used (see validate)
--   entry : 0x50 bytes per species (PKHeX PersonalInfoORAS), index = Dex number
--   growth: byte 0x15 of the entry (PersonalInfoORAS.EXPGrowth), values 0..5
-- Accepted shapes: one file with length % 0x50 == 0 and >= 722 entries, or
-- >= 722 files of 0x50 bytes (file species + 1 is the entry of that species).
local M = {}

M.CANDIDATE_PATHS = { "/a/1/9/5", "/a/1/9/6" }
M.ENTRY_SIZE = 0x50
M.GROWTH_OFFSET = 0x15
M.MIN_ENTRIES = 722 -- species 0..721
M.MAX_ATTEMPTS = 3

function M.new(fb, opts)
  opts = opts or {}
  local paths = opts.paths or M.CANDIDATE_PATHS
  local esize = opts.entry_size or M.ENTRY_SIZE
  local goff = opts.growth_offset or M.GROWTH_OFFSET
  local self = {}
  local rates, attempts = nil, 0

  -- Returns a table species -> rate (1..721) or nil when data is not a personal table.
  local function validate(data)
    local g = fb.codec.garc(data)
    if type(g) ~= "table" or type(g.count) ~= "number" then return nil end
    local out = {}
    if g.count == 1 then
      local whole = fb.codec.garc_file(data, 1, 1)
      if type(whole) ~= "string" or #whole % esize ~= 0 or #whole // esize < M.MIN_ENTRIES then
        return nil
      end
      for s = 1, M.MIN_ENTRIES - 1 do
        local r = whole:byte(s * esize + goff + 1)
        if not r or r > 5 then return nil end
        out[s] = r
      end
    elseif g.count >= M.MIN_ENTRIES then
      for s = 1, M.MIN_ENTRIES - 1 do
        local e = fb.codec.garc_file(data, s + 1, 1)
        if type(e) ~= "string" or #e ~= esize then return nil end
        local r = e:byte(goff + 1)
        if r > 5 then return nil end
        out[s] = r
      end
    else
      return nil
    end
    return out
  end

  local function load()
    if rates then return true end
    if attempts >= M.MAX_ATTEMPTS then return false end
    attempts = attempts + 1
    if not (fb and fb.rom and fb.rom.romfs and fb.codec and fb.codec.garc and fb.codec.garc_file) then
      return false
    end
    for _, path in ipairs(paths) do
      local data = fb.rom.romfs(path)
      if type(data) == "string" then
        local r = validate(data)
        if r then
          rates = r
          self.path = path
          if fb.log and fb.log.info then fb.log.info("personal data accepted at " .. path) end
          return true
        end
      end
    end
    return false
  end

  -- Growth rate 0..5 for a species (Dex number 1..721), or nil.
  function self.growth_rate(species)
    if math.type(species) ~= "integer" or species < 1 then return nil end
    if not load() then return nil end
    return rates[species]
  end

  -- Forget failures and cached values (e.g. after a game change).
  function self.reset()
    rates, attempts, self.path = nil, 0, nil
  end

  return self
end

return M

end
__mod["gen6.pk6"] = function(...)
-- Gen 6 PK6 parser for decrypted data (232 stored / 260 party bytes).
-- Layout: PKHeX PK6.cs (kwsch/PKHeX, PKHeX.Core/PKM/PK6.cs), offsets below are
-- from that file; cross-check: Project Pokemon "Pokemon X/Y save structure".
-- Strings are UTF-16LE, 12 characters + terminator (0x1A bytes).
local M = {}

M.SIZE_STORED = 232
M.SIZE_PARTY = 260
M.MAX_SPECIES = 721 -- ORAS National Dex

local OFF = {
  ec = 0x00, checksum = 0x06, species = 0x08, held_item = 0x0A, tid = 0x0C, sid = 0x0E,
  exp = 0x10, ability = 0x14, pid = 0x18, nature = 0x1C, flags = 0x1D, evs = 0x1E,
  nickname = 0x40, moves = 0x5A, iv32 = 0x74, ot_name = 0xB0, version = 0xDF, language = 0xE3,
  -- party extension (not trusted for live party memory, see parse)
  status = 0xE8, level = 0xEC, hp = 0xF0, max_hp = 0xF2, stats = 0xF4,
}
M.OFF = OFF

-- Language byte (PKHeX LanguageID) -> language code
local LANG = { [1] = "ja", [2] = "en", [3] = "fr", [4] = "it", [5] = "de", [6] = "es",
  [8] = "ko", [9] = "zh-Hans", [10] = "zh-Hant" }
M.LANGUAGES = LANG

local GENDER = { [0] = "male", [1] = "female", [2] = "genderless" }

-- UTF-16LE (up to max_chars code units, stops at 0x0000) -> UTF-8
function M.utf16le_to_utf8(s, max_chars)
  local out, i, n = {}, 1, 0
  max_chars = max_chars or (#s // 2)
  while n < max_chars and i + 1 <= #s do
    local u = string.unpack("<I2", s, i)
    i = i + 2
    n = n + 1
    if u == 0 then break end
    if u >= 0xD800 and u <= 0xDBFF and n < max_chars and i + 1 <= #s then
      local lo = string.unpack("<I2", s, i)
      if lo >= 0xDC00 and lo <= 0xDFFF then
        i = i + 2
        n = n + 1
        out[#out + 1] = utf8.char(0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00))
      else
        out[#out + 1] = utf8.char(0xFFFD)
      end
    elseif u >= 0xD800 and u <= 0xDFFF then
      out[#out + 1] = utf8.char(0xFFFD)
    else
      out[#out + 1] = utf8.char(u)
    end
  end
  return table.concat(out)
end

-- plain: decrypted PK6 (232 or 260 bytes). Returns record or nil, reason.
-- Level/HP/status of the live party are NOT filled from 0xE8+ (unreliable in
-- running ORAS memory); they are exposed as record.party_ext only.
function M.parse(plain)
  if type(plain) ~= "string" then return nil, "bad_type" end
  if #plain ~= M.SIZE_STORED and #plain ~= M.SIZE_PARTY then return nil, "bad_length" end
  local function u8(o) return (string.unpack("<I1", plain, o + 1)) end
  local function u16(o) return (string.unpack("<I2", plain, o + 1)) end
  local function u32(o) return (string.unpack("<I4", plain, o + 1)) end

  local pid, tid, sid = u32(OFF.pid), u16(OFF.tid), u16(OFF.sid)
  local flags = u8(OFF.flags)
  local iv32 = u32(OFF.iv32)
  local moves = {}
  for i = 0, 3 do
    local m = u16(OFF.moves + i * 2)
    if m ~= 0 then moves[#moves + 1] = m end
  end
  local evs, ivs = {}, {}
  for i, k in ipairs({ "hp", "atk", "def", "spe", "spa", "spd" }) do
    evs[k] = u8(OFF.evs + i - 1)
    ivs[k] = (iv32 >> (5 * (i - 1))) & 0x1F
  end
  local lang_id = u8(OFF.language)

  local rec = {
    species = u16(OFF.species),
    form = flags >> 3,
    nickname = M.utf16le_to_utf8(plain:sub(OFF.nickname + 1, OFF.nickname + 0x1A), 12),
    nicknamed = (iv32 >> 31) & 1 == 1,
    exp = u32(OFF.exp),
    personality = pid,
    encryption_constant = u32(OFF.ec),
    shiny = ((tid ~ sid ~ (pid >> 16) ~ (pid & 0xFFFF)) < 16),
    gender = GENDER[(flags >> 1) & 3],
    fateful = flags & 1 == 1,
    nature = u8(OFF.nature),
    ability = u8(OFF.ability),
    held_item = u16(OFF.held_item),
    moves = moves,
    ot_name = M.utf16le_to_utf8(plain:sub(OFF.ot_name + 1, OFF.ot_name + 0x1A), 12),
    ot_id = tid,
    ot_sid = sid,
    language = LANG[lang_id],
    language_id = lang_id,
    origin_game = u8(OFF.version),
    egg = (iv32 >> 30) & 1 == 1,
    ivs = ivs,
    evs = evs,
    -- level, hp, max_hp, status: nil here; level comes from growth
  }
  if #plain == M.SIZE_PARTY then
    local stats = {}
    for i, k in ipairs({ "atk", "def", "spe", "spa", "spd" }) do
      stats[k] = u16(OFF.stats + (i - 1) * 2)
    end
    rec.party_ext = {
      status = u32(OFF.status), level = u8(OFF.level),
      hp = u16(OFF.hp), max_hp = u16(OFF.max_hp), stats = stats,
    }
  end
  return rec
end

return M

end
__mod["main"] = function(...)
-- Entry module of the Pokemon Core plugin.
local games = require("core.games")
local adapters = require("core.adapters")
local interface = require("core.interface")
local serialize = require("core.serialize")

local TEAM_EVERY = 15

local entry, detected = games.detect(fb.game)
if not entry then
  fb.log.info(fb.i18n.t("not_pokemon"))
  return
end

local adapter
local adapter_mod = adapters.get(entry.adapter)
if adapter_mod then
  local ok, result = pcall(adapter_mod.attach, { fb = fb, game = entry, detected = detected })
  if ok and type(result) == "table" then
    adapter = result
  else
    fb.log.error(fb.i18n.t("adapter_failed", { name = entry.name, error = tostring(result) }))
  end
end
if not adapter then
  fb.log.warn(fb.i18n.t("no_adapter", { name = entry.name }))
end

local api = interface.new(entry, detected, adapter)
fb.provide("pokemon.core", api)

if adapter then
  fb.events.emit("game.detected", { game_id = entry.id, gen = entry.gen, supported = true })

  local ticks, last = 0, nil
  fb.on_tick(function()
    ticks = ticks + 1
    if ticks % TEAM_EVERY ~= 0 then return end
    local team = api.team()
    if type(team) ~= "table" then return end
    local s = serialize.serialize(team)
    if s ~= last then
      last = s
      fb.events.emit("team.changed", { team = team })
    end
  end)
end

end
require("main")
